  const active = get("SELECT COUNT(DISTINCT customer_id) n FROM sales WHERE date LIKE ? AND customer_id IS NOT NULL", m + '%').n, pts = Math.floor(get("SELECT COALESCE(SUM(total),0) s FROM sales WHERE customer_id IS NOT NULL").s / 100);
  const cs = all(`SELECT c.*,(SELECT MAX(date) FROM sales WHERE customer_id=c.id) last,(SELECT COALESCE(SUM(total),0) FROM sales WHERE customer_id=c.id AND date LIKE ?) yr FROM customers c ${type ? 'WHERE c.type=?' : ''} ORDER BY c.balance DESC, c.name`, ...[yr + '%'].concat(type ? [type] : []));
