  const imp = q.get('imp') && role === 'owner' ? `<div class="pn"><h2>Import customers</h2><form method="post" action="/admin/customers/import"><label class="f">One customer per line: name, phone, type (Retail/Dealer/Wholesale), address<textarea name="csv" rows="6" style="width:100%" placeholder="Rahim Cycle Store, 01711000000, Dealer, Agrabad"></textarea></label><p><button class="btn">Import</button></p></form></div>` : '';
