POSTS['/admin/service'] = f => { if (!f.get('work')) throw new Error('Describe the work'); const id = +run('INSERT INTO jobs(date,customer_id,frame_no,work,claim,charge) VALUES(?,?,?,?,?,?)', today(), +f.get('customer_id') || null, f.get('frame_no') || '', f.get('work'), f.get('claim') ? 1 : 0, num(f.get('charge'))).lastInsertRowid; return go('/admin/service', jobNo(id) + ' created'); };
